  for (const row of data) { const changed = changes.fields.get(row.id); const valueCells: [keyof HotelRow, string | number][] = [["hotel", row.hotel], ["team", row.team], ["role", row.role], ["guest", row.guest], ["roomType", row.roomType], ["payment", row.payment], ["payBy", row.payBy], ["confirmation", row.confirmation]]; rows.push([...valueCells.map(([key, value]) => ({ value, style: changed?.has(key) ? 5 : 4 })), ...dates.map((date) => ({ value: occupancy(row, date), style: changed?.has("checkIn") || changed?.has("checkOut") ? 5 : 4 })), { value: row.nights, style: changed?.has("nights") ? 5 : 4 }, { value: row.rate, style: changed?.has("rate") ? 5 : 7 }, { value: row.rate * row.nights, style: changed?.has("rate") || changed?.has("nights") ? 5 : 7 }]); }
  rows.push([{ value: "TOTAL ROOMS / NIGHTS", style: 6 }, ...Array(7).fill({ value: "", style: 6 }), ...dates.map((date) => ({ value: data.reduce((sum, row) => sum + (occupancy(row, date) === "1" ? 1 : 0), 0), style: 6 })), { value: data.reduce((sum, row) => sum + row.nights, 0), style: 6 }, { value: "", style: 6 }, { value: data.reduce((sum, row) => sum + row.rate * row.nights, 0), style: 8 }]);
  return { rows, widths: [22, 15, 20, 22, 17, 18, 14, 18, ...dates.map(() => 9), 13, 12, 14] };
