  for (const row of data) { const changed = changes.fields.get(row.id); const cells: [keyof CarRow, string][] = [["date", row.date], ["time", row.time], ["traveler", row.traveler], ["pickup", row.pickup], ["dropoff", row.dropoff], ["vehicle", row.vehicle], ["provider", row.provider], ["confirmation", row.confirmation], ["status", row.status], ["notes", row.notes]]; rows.push(cells.map(([key, value]) => ({ value, style: changed?.has(key) ? 5 : 4 }))); }
