function downloadWorkbook(filename: string, sheetName: string, rows: SheetCell[][], widths: number[]) {
  const blob = createWorkbookBlob(sheetName, rows, widths); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = filename; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}
